import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { FaUserPlus, FaUser, FaLock, FaSchool, FaEnvelope, FaPhone } from 'react-icons/fa';

function Register() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: '',
    phone: '',
    schoolId: '',
    role: 'parent',
    address: ''
  });

  const [errors, setErrors] = useState({});
  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.name.trim()) newErrors.name = 'Name is required';
    if (!formData.email.trim()) newErrors.email = 'Email is required';
    else if (!/\S+@\S+\.\S+/.test(formData.email)) newErrors.email = 'Email is invalid';
    if (!formData.password) newErrors.password = 'Password is required';
    else if (formData.password.length < 6) newErrors.password = 'Password must be at least 6 characters';
    if (formData.password !== formData.confirmPassword) newErrors.confirmPassword = 'Passwords do not match';
    if (!formData.phone.trim()) newErrors.phone = 'Phone is required';
    else if (!/^\d{10}$/.test(formData.phone)) newErrors.phone = 'Phone must be 10 digits';
    if (!formData.schoolId.trim()) newErrors.schoolId = 'School ID is required';
    if (!formData.address.trim()) newErrors.address = 'Address is required';

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    // Simulate registration - replace with actual API call
    const user = {
      ...formData,
      id: Date.now(),
      createdAt: new Date().toLocaleString(),
      status: 'active'
    };

    // Store user in localStorage
    localStorage.setItem('user', JSON.stringify(user));

    // Redirect to dashboard
    navigate('/dashboard');
  };

  return (
    <div className="py-5">
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-8 col-lg-6">
            <div className="card-custom">
              <div className="card-header text-center">
                <h3><FaUserPlus className="me-2" /> Register New Account</h3>
                <p className="mb-0">Join our school facility portal</p>
              </div>
              <div className="card-body p-4">
                <form onSubmit={handleSubmit}>
                  <div className="row">
                    <div className="col-md-6 mb-3">
                      <label className="form-label">
                        <FaUser className="me-2" /> Full Name
                      </label>
                      <input
                        type="text"
                        name="name"
                        className="form-control form-control-lg"
                        placeholder="Enter your name"
                        value={formData.name}
                        onChange={handleChange}
                      />
                      {errors.name && <div className="text-danger small mt-1">{errors.name}</div>}
                    </div>

                    <div className="col-md-6 mb-3">
                      <label className="form-label">
                        <FaPhone className="me-2" /> Phone Number
                      </label>
                      <input
                        type="tel"
                        name="phone"
                        className="form-control form-control-lg"
                        placeholder="10 digit phone"
                        value={formData.phone}
                        onChange={handleChange}
                      />
                      {errors.phone && <div className="text-danger small mt-1">{errors.phone}</div>}
                    </div>
                  </div>

                  <div className="mb-3">
                    <label className="form-label">
                      <FaEnvelope className="me-2" /> Email Address
                    </label>
                    <input
                      type="email"
                      name="email"
                      className="form-control form-control-lg"
                      placeholder="Enter email"
                      value={formData.email}
                      onChange={handleChange}
                    />
                    {errors.email && <div className="text-danger small mt-1">{errors.email}</div>}
                  </div>

                  <div className="row">
                    <div className="col-md-6 mb-3">
                      <label className="form-label">
                        <FaLock className="me-2" /> Password
                      </label>
                      <input
                        type="password"
                        name="password"
                        className="form-control form-control-lg"
                        placeholder="Min 6 characters"
                        value={formData.password}
                        onChange={handleChange}
                      />
                      {errors.password && <div className="text-danger small mt-1">{errors.password}</div>}
                    </div>

                    <div className="col-md-6 mb-3">
                      <label className="form-label">
                        <FaLock className="me-2" /> Confirm Password
                      </label>
                      <input
                        type="password"
                        name="confirmPassword"
                        className="form-control form-control-lg"
                        placeholder="Re-enter password"
                        value={formData.confirmPassword}
                        onChange={handleChange}
                      />
                      {errors.confirmPassword && <div className="text-danger small mt-1">{errors.confirmPassword}</div>}
                    </div>
                  </div>

                  <div className="row">
                    <div className="col-md-6 mb-3">
                      <label className="form-label">
                        <FaSchool className="me-2" /> School ID
                      </label>
                      <input
                        type="text"
                        name="schoolId"
                        className="form-control form-control-lg"
                        placeholder="Enter school ID"
                        value={formData.schoolId}
                        onChange={handleChange}
                      />
                      {errors.schoolId && <div className="text-danger small mt-1">{errors.schoolId}</div>}
                    </div>

                    <div className="col-md-6 mb-3">
                      <label className="form-label">Role</label>
                      <select
                        name="role"
                        className="form-select form-select-lg"
                        value={formData.role}
                        onChange={handleChange}
                      >
                        <option value="parent">Parent</option>
                        <option value="teacher">Teacher</option>
                      </select>
                    </div>
                  </div>

                  <div className="mb-4">
                    <label className="form-label">Address</label>
                    <textarea
                      name="address"
                      className="form-control form-control-lg"
                      rows="3"
                      placeholder="Enter full address"
                      value={formData.address}
                      onChange={handleChange}
                    />
                    {errors.address && <div className="text-danger small mt-1">{errors.address}</div>}
                  </div>

                  <div className="d-grid gap-2">
                    <button type="submit" className="btn btn-custom btn-lg">
                      <FaUserPlus className="me-2" /> Register
                    </button>
                  </div>

                  <div className="text-center mt-4">
                    <p className="mb-0">
                      Already have an account? 
                      <Link to="/login" className="text-primary ms-2">Login Here</Link>
                    </p>
                  </div>
                </form>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Register;
